"""Sum integers.

    Arguments:
        *args: One or more integers.

    Returns:
        Sum of integers.

    Raises:
        TypeError: No argument was passed or a passed argument is not of type
            `int`.

    Example:
        >>> add_integers(3, 4)
        7
    """
def add_integers(*args: int) -> int {
    if not len(args) {
        raise TypeError(f"{add_integers.__name__}() requires at least one argument");
    }
    for i in args {
        if not isinstance(i, int) {
            raise TypeError(
                f'''Passed argument of type '{type(
                    i
                ).__name__}', but only "
                f"integers allowed: {i}'''
            );
        }
    }
    return sum(args);
}

"""
         Convert moles/m2 to molec/cm2
    """
def molm2_to_molec_cm2(spc_array: Any) -> object {
    avo_num = 6.0221409e+23;
    molec_per_m2 = spc_array * avo_num;
    molec_per_cm2 = molec_per_m2 * 10000.0;
    return molec_per_cm2;
}

"""Calculate power loss in the transistor."""
def transistor_power(vcc_max: Any, i_out: Any, r_load: Any, r_set: Any) -> object {
    r_tot = r_load + r_set;
    max_pwr_i = vcc_max / (2 * r_tot);
    load_rdrop = max_pwr_i * r_tot;
    v_trans = vcc_max - load_rdrop;
    return (max_pwr_i * v_trans);
}

"""
    Determines if a 11-digit GEOID (from the US census files) refers to the same place as a six-digit Chicago census
    tract ID.

    :param tract_id: A 6-digit Chicago census tract ID (i.e., '821402')
    :param geo_id: An 11-digit GEOID from the US Census "Gazetteer" files (i.e., '17031821402')
    :return: True if equivalent, False otherwise
    """
def tract_id_equals(tract_id: Any, geo_id: Any) -> object {
    return (geo_id.startswith("1703") and (tract_id == geo_id[-6:]));
}

"""
    Drops only the keys of a dict that do **not** have the same name as the keys in a source dictionnary.
    Return dictionnary containing the rest.

    Args:
        dict_to_modify (TYPE): DESCRIPTION.
        source_dict (TYPE): DESCRIPTION.

    Returns:
        modified_dict (TYPE): DESCRIPTION.

    """
def keep_matched_keys(dict_to_modify: Any, model_keys: Any) -> object {
    if isinstance(model_keys, `dict) {
        model_keys = `set(model_keys.keys());
    }
    return {
        kept_key: dict_to_modify[kept_key]
        for kept_key in model_keys
        if ((kept_key != 'empty') and (dict_to_modify.get(kept_key) is not None))
    };
}

"""
    The two input directories are supposed to be to the same level. Find how many
    directory levels are given in correctRelDir, and return the same number of levels
    from the end of absDir. Also return the topDir, which is the components of absDir
    above the level of correctRelativeDir

    """
def matchSubdirLevel(absDir: Any, correctRelDir: Any) -> object {
    numLevels = len(correctRelDir.split('/'));
    absDirComponents = absDir.split('/');
    matchingSubdir = '/'.join(absDirComponents[1:][-numLevels:]);
    topDir = '/'.join(absDirComponents[:-numLevels]);
    return (matchingSubdir, topDir);
}
